sys_ui_action.script:
// bfd_ui_repair_demo_data — list banner button on the fraud / dispute case list.
//
// Runs the idempotent remediation in bfd_DemoDataRepair: stamps the missing
// CUST / TXN / CASE / TASK display numbers on the already-installed demo data
// and backfills the empty bfd_case_metric_snapshot table. Reports the per-table
// counts back to the user with gs.addInfoMessage.
(function repairDemoDataAction() {
    var result;

    try {
        result = new bfd_DemoDataRepair().repairAll();
    } catch (e) {
        gs.addErrorMessage('Demo data repair failed: ' + e);
        gs.error('[bfd_ui_repair_demo_data] ' + e);
        return;
    }

    if (!result) {
        gs.addErrorMessage('Demo data repair returned no result. Check the system log for details.');
        return;
    }

    gs.addInfoMessage(result.summary);

    var tables = (result.numbers && result.numbers.tables) || [];
    for (var i = 0; i < tables.length; i++) {
        var entry = tables[i];
        gs.addInfoMessage(
            entry.label +
                ' (' +
                entry.table +
                '.' +
                entry.field +
                '): ' +
                entry.updated +
                ' record(s) numbered' +
                (entry.updated && entry.first ? ', starting at ' + entry.first : '') +
                (entry.error ? ' — error: ' + entry.error : '') +
                '.'
        );
    }

    var snapshots = result.snapshots || {};
    gs.addInfoMessage(
        'Metric snapshots: ' +
            (snapshots.created || 0) +
            ' created, ' +
            (snapshots.skipped || 0) +
            ' already existed, ' +
            (snapshots.scanned || 0) +
            ' resolved/closed case(s) scanned. Re-running this action is safe.'
    );
})();
